node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

// 1. Check cellular service is on
const settings = db.prepare(\"SELECT cellular FROM ts_device_settings WHERE device_id = 'device_0'\").get();
if (!settings || !settings.cellular) {
    console.log(JSON.stringify({ok: false, error: 'Cellular service is not enabled'}));
    process.exit(0);
}

// 2. Find self contact
const selfContact = db.prepare(\"SELECT * FROM ts_contacts WHERE is_self = 1\").all();
if (selfContact.length !== 1) {
    console.log(JSON.stringify({ok: false, error: 'Could not find unique self contact'}));
    process.exit(0);
}

// 3. Find recipient by phone number
const recipientPhone = '+1-415-555-0187';
const recipient = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = ?\").get(recipientPhone);

// 4. Create message
const messageId = crypto.randomUUID();
const content = 'Hi Maya, I wanted to let you know that I checked the compatibility of the Magnetic Wireless Charging Stand (PROD-2028EE) with the TechPhone Pro 16, and unfortunately compatibility cannot be confirmed based on the available catalog data. The product\\'s compatibility list doesn\\'t include the TechPhone Pro 16. You may want to check with the manufacturer (VoltForge) or verify that the TechPhone Pro 16 supports Qi wireless charging before purchasing.';
const now = Date.now() / 1000;

const stmt = db.prepare(
    'INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
);

stmt.run(
    messageId,
    selfContact[0].person_id,
    selfContact[0].phone_number,
    recipient ? recipient.person_id : null,
    recipientPhone,
    content,
    now,
    new Date().toISOString()
);

console.log(JSON.stringify({
    ok: true,
    result: {
        message_id: messageId,
        sender: selfContact[0].name + ' (' + selfContact[0].phone_number + ')',
        recipient: (recipient ? recipient.name : 'Unknown') + ' (' + recipientPhone + ')',
        content: content
    }
}, null, 2));
"

